// Hardcoded, pre-baked BPM/key/Camelot for the catalogue.
//
// analysis.json is generated by scripts/bake-analysis.mjs (the real DJ engine run
// over every track once) and committed to the repo, so EVERY visitor sees tracks
// already analysed — no per-user work, no matter who first analysed them. Keyed by
// the track's full media URL (same string as TRACKS[i].src).
import baked from './analysis.json';

export const ANALYSIS = (baked && baked.byUrl) || {};

// Look up a baked result by track src. Returns { bpm, key, camelot } or null.
export function analysisFor(src) {
  return (src && ANALYSIS[src]) || null;
}
